  const P = (slot) => window.BIO.views.photo(slot);
  const d2 = (counts) => M.fix(M.index(counts).d, 2);
  const D = (key) => M.dOf(key);
  const tbl = (rows, head = ["Species", "Number of individuals, n"]) => `<table class="tbl"><thead><tr>${head.map((h) => `<th>${h}</th>`).join("")}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table>`;
  const comTable = (key) => tbl(CM[key].species);
  const ev = (rows) => `<ul class="small">${rows.map(([k, v]) => `<li>${k}: <strong>${v}</strong></li>`).join("")}</ul>`;
  const ix = (counts) => M.index(counts);
  // Worked values quoted in the text (each checked by hand in the author report)
  const dA = D("evenA"), dB = D("unevenB"), dM = D("margin"), dC = D("crop"), dMg = D("mangrove"), dSf = D("sandflat");
  const shore = [15, 10, 8, 4, 3], dShore = ix(shore);
  const pondX = [12, 8, 5, 3, 1, 1], pondY = [30, 3, 2, 1], dPX = ix(pondX), dPY = ix(pondY);
  const tiny = ix([4, 3, 2]);
